                var bestIndex = -1;
                for (var o = 0; o < size(others); o += 1)
                {
                    const ends = evEdgeTangentLines(context, { "edge" : others[o], "parameters" : [0, 1] });
                    for (var k = 0; k < 2; k += 1)
                    {
                        const d = norm(ends[k].origin - mergedEnds[e].origin);
                        if (d < best)
                        {
                            best = d;
                            bestIndex = o;
                        }
                    }
