function curveTypeName(curveType) returns string
{
    if (curveType == CurveType.LINE) { return "line"; }
    if (curveType == CurveType.CIRCLE) { return "circle"; }
    if (curveType == CurveType.ELLIPSE) { return "ellipse"; }
    return "other";
